"""Media transforms. All working filenames are generated by us under a temp directory."""
from array import array
import json
import sys
import subprocess
from math import isfinite


def run(cmd, cwd):
    subprocess.run(cmd, cwd=cwd, check=True, stdin=subprocess.DEVNULL)


def probe(path):
    cmd = ["ffprobe", "-v", "error", "-of", "json", "-show_streams", "-show_format", str(path)]
    return json.loads(subprocess.check_output(cmd))


def seconds(path):
    return float(probe(path)["format"]["duration"])


def analyze_audio(path, length):
    """Measure 100 ms windows at 8 kHz. Require half a second above -40 dBFS."""
    cmd = ["ffmpeg", "-nostdin", "-v", "error", "-i", str(path), "-t", str(min(length, 46)),
           "-map", "0:a:0", "-ac", "1", "-ar", "8000", "-f", "s16le", "-"]
    samples = array("h", subprocess.check_output(cmd))
    if sys.byteorder != "little":
        samples.byteswap()
    first, count = None, 0
    for pos in range(0, len(samples), 800):
        window = samples[pos:pos + 800]
        if sum(v*v for v in window) >= (32768 * .01)**2 * len(window):
            if first is None:
                first = pos / 8000
            count += len(window)
    return min(1.5, max(0, (first or 0) - .1)), count >= 4000


def safe(text):
    # Prevent source text from becoming an ASS override, newline, or positioning command.
    return " ".join(str(text).translate(str.maketrans({"\\": "／", "{": "(", "}": ")"})).split())


def stamp(t):
    cs = max(0, round(t * 100))
    return f"{cs // 360000}:{cs // 6000 % 60:02}:{cs // 100 % 60:02}.{cs % 100:02}"


def subtitles(path, words, length, title, name, notes=()):
    lines = ["""[Script Info]
ScriptType: v4.00+
PlayResX: 1080
PlayResY: 1920
WrapStyle: 0
[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Caption,DejaVu Sans,68,&H0000E7FF,&H00FFFFFF,&H00090909,&H70000000,-1,0,0,0,100,100,0,0,1,5,2,5,86,86,0,1
Style: Hook,DejaVu Sans,64,&H00FFFFFF,&H00FFFFFF,&H00302014,&H80302014,-1,0,0,0,100,100,0,0,3,12,0,8,80,80,260,1
Style: Credit,DejaVu Sans,42,&H00FFFFFF,&H00FFFFFF,&H00151515,&H70000000,-1,0,0,0,100,100,0,0,1,3,1,2,65,65,320,1
[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text"""]
    def add(start, end, style, value):
        if end > start:
            lines.append(f"Dialogue: 0,{stamp(start)},{stamp(end)},{style},,0,0,0,,{value}")
    add(0, length, "Hook", safe(title)[:68])
    add(0, length, "Credit", "Credit: " + safe(name)[:75])
    for note in notes:
        add(max(0, float(note["start"])), min(length, float(note["end"])), "Credit",
            r"{\an5\pos(540,1470)}" + safe(note["text"])[:150])
    for i, (start, end, word) in enumerate(words):
        # Keep adjacent text visible while highlighting exactly the spoken word.
        group = i // 3 * 3
        phrase = " ".join((r"{\1c&H00E7FF&}" if j == i else r"{\1c&HFFFFFF&}") + safe(w)
                          for j, (_, _, w) in enumerate(words[group:group+3], group))
        add(max(0, start), min(end, length), "Caption", r"{\pos(540,1070)}" + phrase)
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def render(source, out, length, words, title, credit, notes=(), facecam=None, start=0):
    ass = out.with_suffix(".ass")
    subtitles(ass, words, length, title, credit, notes)
    audio = any(s["codec_type"] == "audio" for s in probe(source)["streams"])
    # Brief center punch-in on each cut, then settle back to uncropped gameplay.
    vf = ("[0:v]fps=30,setsar=1,split[back][front];"
          "[back]scale=270:480:force_original_aspect_ratio=increase,crop=270:480,"
          "boxblur=12:2,scale=1080:1920,eq=brightness=-0.12[bg];"
          "[front]scale=1080:960:force_original_aspect_ratio=decrease:force_divisible_by=2,"
          "pad=1080:960:(ow-iw)/2:(oh-ih)/2:color=black,"
          "zoompan=z='1+0.10*max(0,1-on/12)':x='iw/2-iw/zoom/2':"
          "y='ih/2-ih/zoom/2':d=1:s=1080x960:fps=30[fg];"
          f"[bg][fg]overlay=(W-w)/2:(H-h)/2,setsar=1,ass={ass.name}[v]")
    if facecam is not None:
        x, y, w, h = map(float, facecam)  # normalized left, top, width, height
        if not (all(isfinite(v) for v in (x, y, w, h)) and min(x, y) >= 0
                and min(w, h) > 0 and x+w <= 1 and y+h <= 1):
            raise ValueError("Invalid normalized facecam crop in editorial.json")
        vf = (f"[0:v]fps=30,setsar=1,split[cam][game];"
              f"[cam]crop=iw*{w}:ih*{h}:iw*{x}:ih*{y},"
              "scale=1080:640:force_original_aspect_ratio=increase,crop=1080:640,setsar=1[top];"
              "[game]scale=1080:1280:force_original_aspect_ratio=increase,crop=1080:1280,"
              "zoompan=z='1+0.10*max(0,1-on/12)':x='iw/2-iw/zoom/2':"
              "y='ih/2-ih/zoom/2':d=1:s=1080x1280:fps=30,setsar=1[bottom];"
              f"[top][bottom]vstack,ass={ass.name}[v]")
    cmd = ["ffmpeg", "-nostdin", "-loglevel", "error", "-y", "-filter_complex_threads", "2",
           "-ss", str(start), "-i", source.name]
    if not audio:
        cmd += ["-f", "lavfi", "-i", "anullsrc=r=44100:cl=stereo"]
    cmd += ["-filter_complex", vf, "-map", "[v]", "-map", "0:a:0" if audio else "1:a:0",
            "-af", "apad", "-t", f"{length:.3f}", "-c:v", "libx264", "-threads", "2",
            "-preset", "ultrafast", "-crf", "23", "-pix_fmt", "yuv420p", "-c:a", "aac",
            "-b:a", "128k", "-ar", "44100", "-ac", "2", "-movflags", "+faststart", out.name]
    run(cmd, out.parent)


def join(parts, out):
    listing = out.parent / "parts.txt"
    listing.write_text("".join(f"file '{p.name}'\n" for p in parts))
    run(["ffmpeg", "-nostdin", "-loglevel", "error", "-y", "-f", "concat", "-safe", "1",
         "-i", listing.name, "-c", "copy", "-movflags", "+faststart", out.name], out.parent)
